    assert.deepEqual(result, { ok: false, error: 'DISCOUNT_INVALID' }, `Failed for discount: ${discount}`);
  }
});

test('createInvoice accepts boundary discounts 0 and 100', () => {
  for (const discount of [0, 100]) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: discount }],
    });
    assert.equal(result.ok, true, `Failed for discount: ${discount}`);
  }
});

test('lineDiscount returns 0 when no discountPercent', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };

  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount calculates discount correctly', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 10,
  };

  // lineTotal = 10 × 9500 = 95000
  // discount = 95000 × 10 / 100 = 9500
  assert.equal(lineDiscount(line), 9500);
});

test('lineDiscount with decimal percentage', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 12.5,
  };

  // lineTotal = 10 × 9500 = 95000
  // discount = 95000 × 12.5 / 100 = 11875
  assert.equal(lineDiscount(line), 11875);
});

test('lineDiscount rounds correctly', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 3,
    unitPrice: 100,
    vatRate: 21,
    discountPercent: 33,
  };

  // lineTotal = 3 × 100 = 300
  // discount = 300 × 33 / 100 = 99 (exactly)
  assert.equal(lineDiscount(line), 99);
});

test('lineDiscount with 0% discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 0,
  };

  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount with 100% discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 100,
  };

  // lineTotal = 10 × 9500 = 95000
  // discount = 95000 × 100 / 100 = 95000
  assert.equal(lineDiscount(line), 95000);
});

test('invoiceTotals returns { subtotal, discount, total } structure', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  const totals = invoiceTotals(result.value);
  assert.ok('subtotal' in totals);
  assert.ok('discount' in totals);
  assert.ok('total' in totals);
  assert.equal(typeof totals.subtotal, 'number');
  assert.equal(typeof totals.discount, 'number');
  assert.equal(typeof totals.total, 'number');
});

test('invoiceTotals with single line discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // lineTotal = 10 × 9500 = 95000
  // discount = 95000 × 10 / 100 = 9500
  // total = 95000 - 9500 = 85500
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.total, 85500);
});

test('invoiceTotals with multiple lines and discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 20 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 10 × 9500 = 95000, discount = 9500
  // DES-HOUR: 5 × 8500 = 42500, discount = 8500
  // subtotal = 137500, total discount = 18000
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.discount, 18000);
  assert.equal(totals.total, 119500);
});

test('invoiceTotals with mixed discounted and non-discounted lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 10 × 9500 = 95000, discount = 9500
  // DES-HOUR: 5 × 8500 = 42500, discount = 0
  // subtotal = 137500, total discount = 9500
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.total, 128000);
});

test('invoiceTotals total never goes below zero', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 100 }],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 95000);
  assert.equal(totals.total, 0);
});

test('addLine accepts and stores discountPercent', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3, discountPercent: 15 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 15);
});

test('addLine validates discountPercent on new lines', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3, discountPercent: 150 });
  assert.deepEqual(result, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('addLine updates discountPercent on existing lines', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 10 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

