  // 2 × 1.75 = 3.5, rounds to 4 (even)
  assert.equal(lineTotal(line2), 4);
});

test('invoiceTotals returns subtotal and total for single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.total, 95000);
});

test('invoiceTotals sums multiple line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 10 × 9500 = 95000
  // DES-HOUR: 5 × 8500 = 42500
  // Total: 137500
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.total, 137500);
});

test('invoiceTotals sums complex line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'STICKER', qty: 50 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 8 × 9500 = 76000
  // DES-HOUR: 3 × 8500 = 25500
  // ICON-SET: 2 × 980 = 1960
  // STICKER: 50 × 50 = 2500
  // Total: 105960
  assert.equal(totals.subtotal, 105960);
  assert.equal(totals.total, 105960);
});

test('invoiceTotals returns { subtotal, total } with correct structure', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

