    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
  };

  assert.equal(lineTotal(line), 120000);
});

test('lineTotal rounds fractional cents', () => {
  const line = {
    sku: 'CUSTOM',
    name: 'Custom item',
    qty: 3,
    unitPrice: 100.33,
    vatRate: 21,
  };

  // 3 × 100.33 = 300.99
  assert.equal(lineTotal(line), 301);
});

test('lineTotal rounds half to even', () => {
  const line1 = {
    sku: 'CUSTOM',
    name: 'Custom item',
    qty: 2,
    unitPrice: 1.25,
    vatRate: 21,
  };

  const line2 = {
    sku: 'CUSTOM',
    name: 'Custom item',
    qty: 2,
    unitPrice: 1.75,
    vatRate: 21,
