      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 }, // explicit discount
      { sku: 'ICON-SET', qty: 2, discountPercent: 0 }, // explicit 0
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5); // tier
  assert.equal(result.value.lines[1].discountPercent, 10); // explicit
  assert.equal(result.value.lines[2].discountPercent, 0); // explicit 0
});

test('invoiceTotals with tier discount applied', () => {
  // C-001 is gold tier (5%)
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // lineTotal = 10 × 9500 = 95000
  // discount = 95000 × 5 / 100 = 4750
  // total = 95000 - 4750 = 90250
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.total, 90250);
});

test('invoiceTotals with different tier discounts', () => {
  // C-003 is silver tier (2.5%)
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // lineTotal = 10 × 9500 = 95000
  // discount = 95000 × 2.5 / 100 = 2375
  // total = 95000 - 2375 = 92625
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.total, 92625);
});

test('invoiceTotals with standard tier (no discount)', () => {
  // C-002 is standard tier (0%)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 95000);
});

